namespace ContosoUniversity.Tests.Controllers
{
    public sealed class StudentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly StudentsController _controller;

        public StudentsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new StudentsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private Student CreateStudent(string lastName = "Smith", string firstName = "John", DateTime? enrollmentDate = null)
        {
            var student = new Student
            {
                LastName = lastName,
                FirstMidName = firstName,
                EnrollmentDate = enrollmentDate ?? new DateTime(2023, 9, 1)
            };
            _context.Students.Add(student);
            _context.SaveChanges();
            return student;
        }

        #region Index

        [Fact]
        public void Index_NoParameters_ReturnsViewWithAllStudents()
        {
            CreateStudent("Adams", "Alice");
            CreateStudent("Brown", "Bob");

            var result = _controller.Index(null, null, null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(2, model.Count);
        }

        [Fact]
        public void Index_SearchString_FiltersStudentsByLastName()
        {
            CreateStudent("Adams", "Alice");
            CreateStudent("Brown", "Bob");

            var result = _controller.Index(null, null, "Adams", null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Single(model);
            Assert.Equal("Adams", model[0].LastName);
        }

        [Fact]
        public void Index_SearchString_FiltersStudentsByFirstName()
        {
            CreateStudent("Adams", "Alice");
            CreateStudent("Brown", "Bob");

            var result = _controller.Index(null, null, "Bob", null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Single(model);
            Assert.Equal("Brown", model[0].LastName);
        }

        [Theory]
        [InlineData("name_desc", "Brown")] // Descending by last name => Brown first
        [InlineData("", "Adams")]           // Default ascending by last name => Adams first
        public void Index_SortOrder_SortsStudentsCorrectly(string sortOrder, string expectedFirstLastName)
        {
            CreateStudent("Adams", "Alice");
            CreateStudent("Brown", "Bob");

            var result = _controller.Index(sortOrder, null, null, null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(expectedFirstLastName, model[0].LastName);
        }

        [Fact]
        public void Index_DateSort_SortsByEnrollmentDate()
        {
            CreateStudent("Adams", "Alice", new DateTime(2023, 9, 1));
            CreateStudent("Brown", "Bob", new DateTime(2022, 1, 15));

            var result = _controller.Index("Date", null, null, null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal("Brown", model[0].LastName); // Earlier date first
        }

        [Fact]
        public void Index_DateDescSort_SortsByEnrollmentDateDescending()
        {
            CreateStudent("Adams", "Alice", new DateTime(2023, 9, 1));
            CreateStudent("Brown", "Bob", new DateTime(2022, 1, 15));

            var result = _controller.Index("date_desc", null, null, null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal("Adams", model[0].LastName); // Later date first
        }

        [Fact]
        public void Index_NewSearchString_ResetsPageToOne()
        {
            // When searchString is not null, page should be reset to 1
            var result = _controller.Index(null, null, "test", 5) as ViewResult;

            Assert.NotNull(result);
            // Page resets - ViewBag.CurrentFilter should be "test"
        }

        [Fact]
        public void Index_NullSearchString_UsesCurrentFilter()
        {
            CreateStudent("Adams", "Alice");

            var result = _controller.Index(null, "Adams", null, null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Single(model);
        }

