namespace ContosoUniversity.Tests.Controllers
{
    public sealed class CoursesControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly CoursesController _controller;
        private readonly Mock<IWebHostEnvironment> _mockEnv;
        private readonly Mock<ILogger<CoursesController>> _mockLogger;
        private readonly string _tempDir;

        public CoursesControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _mockEnv = new Mock<IWebHostEnvironment>();
            _mockLogger = new Mock<ILogger<CoursesController>>();
            _tempDir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
            Directory.CreateDirectory(_tempDir);
            _mockEnv.Setup(e => e.WebRootPath).Returns(_tempDir);
            _mockEnv.Setup(e => e.ContentRootPath).Returns(_tempDir);
            _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
            if (Directory.Exists(_tempDir))
                Directory.Delete(_tempDir, recursive: true);
        }

        private Department CreateDepartment(string name = "Engineering")
        {
            var dept = new Department { Name = name, Budget = 100000, StartDate = new DateTime(2020, 1, 1) };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            return dept;
        }

        private Course CreateCourse(int courseId = 1001, string title = "Intro to CS", int credits = 3, int? departmentId = null)
        {
            if (departmentId == null)
            {
                var dept = CreateDepartment();
                departmentId = dept.DepartmentID;
            }
            var course = new Course { CourseID = courseId, Title = title, Credits = credits, DepartmentID = departmentId.Value };
            _context.Courses.Add(course);
            _context.SaveChanges();
            return course;
        }

        #region Index

        [Fact]
        public void Index_ReturnsViewWithAllCourses()
        {
            var dept = CreateDepartment();
            CreateCourse(1001, "CS101", 3, dept.DepartmentID);
            CreateCourse(1002, "CS201", 4, dept.DepartmentID);

            var result = _controller.Index() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<List<Course>>(result.Model);
            Assert.Equal(2, model.Count);
        }

        #endregion

        #region Details

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithCourse()
        {
            var course = CreateCourse();

            var result = _controller.Details(course.CourseID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Course>(result.Model);
            Assert.Equal(course.CourseID, model.CourseID);
            Assert.Equal("Intro to CS", model.Title);
        }

        #endregion

        #region Create GET

        [Fact]
        public void Create_Get_ReturnsViewWithDepartmentList()
