        [Fact]
        public void SchoolContext_CanAddAndRetrieveStudent()
        {
            using var context = TestDbContextFactory.Create();

            context.Students.Add(new Student
            {
                LastName = "Test",
                FirstMidName = "User",
                EnrollmentDate = new DateTime(2023, 1, 1)
            });
            context.SaveChanges();

            var student = context.Students.First();
            Assert.Equal("Test", student.LastName);
            Assert.Equal("User", student.FirstMidName);
        }

        [Fact]
        public void SchoolContext_CanAddAndRetrieveCourse()
        {
            using var context = TestDbContextFactory.Create();
            var dept = new Department { Name = "CS", Budget = 100000, StartDate = DateTime.Now };
            context.Departments.Add(dept);
            context.SaveChanges();

            context.Courses.Add(new Course
            {
                CourseID = 1001,
                Title = "Algorithms",
                Credits = 4,
                DepartmentID = dept.DepartmentID
            });
            context.SaveChanges();

            var course = context.Courses.Find(1001);
            Assert.NotNull(course);
            Assert.Equal("Algorithms", course.Title);
            Assert.Equal(4, course.Credits);
        }

        [Fact]
        public void SchoolContext_CourseAssignment_CompositeKey()
        {
            using var context = TestDbContextFactory.Create();
            var instructor = new Instructor
            {
                LastName = "Prof",
                FirstMidName = "X",
                HireDate = DateTime.Now,
                CourseAssignments = new List<CourseAssignment>()
            };
            context.Instructors.Add(instructor);
            var dept = new Department { Name = "CS", Budget = 100000, StartDate = DateTime.Now };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course { CourseID = 100, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };
            context.Courses.Add(course);
            context.SaveChanges();

            var assignment = new CourseAssignment { CourseID = course.CourseID, InstructorID = instructor.ID };
            context.CourseAssignments.Add(assignment);
            context.SaveChanges();

            var saved = context.CourseAssignments.Find(course.CourseID, instructor.ID);
            Assert.NotNull(saved);
        }

        [Fact]
        public void SchoolContext_InstructorOfficeAssignment_OneToOne()
        {
            using var context = TestDbContextFactory.Create();
            var instructor = new Instructor
            {
                LastName = "Prof",
                FirstMidName = "Y",
                HireDate = DateTime.Now,
                CourseAssignments = new List<CourseAssignment>()
            };
            context.Instructors.Add(instructor);
            context.SaveChanges();

            var office = new OfficeAssignment { InstructorID = instructor.ID, Location = "Room 101" };
            context.OfficeAssignments.Add(office);
            context.SaveChanges();

            var loaded = context.Instructors.Include(i => i.OfficeAssignment).First(i => i.ID == instructor.ID);
            Assert.NotNull(loaded.OfficeAssignment);
            Assert.Equal("Room 101", loaded.OfficeAssignment.Location);
        }

        [Fact]
        public void SchoolContext_Enrollment_RelationshipsWork()
        {
            using var context = TestDbContextFactory.Create();
            var student = new Student { LastName = "S", FirstMidName = "T", EnrollmentDate = DateTime.Now };
            context.Students.Add(student);
            var dept = new Department { Name = "D", Budget = 1000, StartDate = DateTime.Now };
            context.Departments.Add(dept);
            context.SaveChanges();
            var course = new Course { CourseID = 200, Title = "C", Credits = 3, DepartmentID = dept.DepartmentID };
            context.Courses.Add(course);
            context.SaveChanges();

            context.Enrollments.Add(new Enrollment
            {
                CourseID = course.CourseID,
                StudentID = student.ID,
                Grade = Grade.A
            });
            context.SaveChanges();

            var enrollment = context.Enrollments.Include(e => e.Course).Include(e => e.Student).First();
            Assert.Equal("C", enrollment.Course.Title);
            Assert.Equal("S", enrollment.Student.LastName);
            Assert.Equal(Grade.A, enrollment.Grade);
        }

        [Fact]
        public void Person_FullName_ReturnsConcatenatedName()
        {
            var student = new Student { LastName = "Doe", FirstMidName = "John", EnrollmentDate = DateTime.Now };
            Assert.Equal("Doe, John", student.FullName);
        }
    }
