using System;
using System.Collections.Generic;
using System.Linq;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using Xunit;
using ContosoUniversity.Tests.Helpers;

namespace ContosoUniversity.Tests
{
    public sealed class PaginatedListTests
    {
        [Fact]
        public void Create_ReturnsCorrectPage()
        {
            var items = Enumerable.Range(1, 25).Select(i => new Student
            {
                LastName = $"Student{i}",
                FirstMidName = "Test",
                EnrollmentDate = DateTime.Now
            }).AsQueryable();

            // Use in-memory db to support IQueryable
            var context = TestDbContextFactory.Create();
            foreach (var s in items)
                context.Students.Add(s);
            context.SaveChanges();

            var query = context.Students.OrderBy(s => s.LastName);
            var page = PaginatedList<Student>.Create(query, 1, 10);

            Assert.Equal(10, page.Count);
            Assert.Equal(1, page.PageIndex);
            Assert.Equal(3, page.TotalPages);
            Assert.False(page.HasPreviousPage);
            Assert.True(page.HasNextPage);

            context.Dispose();
        }

        [Fact]
        public void Create_LastPage_HasPreviousButNoNext()
        {
            var context = TestDbContextFactory.Create();
            for (int i = 0; i < 25; i++)
                context.Students.Add(new Student { LastName = $"S{i:D2}", FirstMidName = "T", EnrollmentDate = DateTime.Now });
            context.SaveChanges();

            var query = context.Students.OrderBy(s => s.LastName);
            var page = PaginatedList<Student>.Create(query, 3, 10);

            Assert.Equal(5, page.Count);
            Assert.Equal(3, page.PageIndex);
            Assert.True(page.HasPreviousPage);
            Assert.False(page.HasNextPage);

            context.Dispose();
        }

        [Fact]
        public void Create_SinglePage_NoPreviousNoNext()
        {
            var context = TestDbContextFactory.Create();
            context.Students.Add(new Student { LastName = "Only", FirstMidName = "One", EnrollmentDate = DateTime.Now });
            context.SaveChanges();

            var query = context.Students.OrderBy(s => s.LastName);
            var page = PaginatedList<Student>.Create(query, 1, 10);

            Assert.Single(page);
            Assert.Equal(1, page.TotalPages);
            Assert.False(page.HasPreviousPage);
            Assert.False(page.HasNextPage);

            context.Dispose();
        }
    }
}

